import{_ as n,c as i,o as t,a3 as a}from"./chunks/framework.CoV49S2T.js";const d=JSON.parse('{"title":"macOS-Berechtigungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/permissions.md","filePath":"de/guide/permissions.md","lastUpdated":1787284674000}'),s={name:"de/guide/permissions.md"};function r(l,e,o,c,u,g){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="macos-berechtigungen" tabindex="-1">macOS-Berechtigungen <a class="header-anchor" href="#macos-berechtigungen" aria-label="Permalink to &quot;macOS-Berechtigungen&quot;">​</a></h1><p>ClipboxAI kann einige macOS-Berechtigungen anfragen, um das beste Erlebnis zu bieten. Diese Seite erklärt, wofür jede Berechtigung dient und wie Sie sie verwalten.</p><h2 id="zwischenablage-automation" tabindex="-1">Zwischenablage / Automation <a class="header-anchor" href="#zwischenablage-automation" aria-label="Permalink to &quot;Zwischenablage / Automation&quot;">​</a></h2><p>Um Ihre Zwischenablage im Hintergrund zu erfassen und Ergebnisse zurück einzufügen, verwendet ClipboxAI den macOS Automation-Zugriff.</p><p><strong>Verwendungszweck</strong>: Das aktuelle Pasteboard beim Kopieren lesen und Ergebnisse zurückschreiben, wenn Sie eine Aktion ausführen.</p><p><strong>Verwalten</strong>: <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit → Automation</strong> → <strong>ClipboxAI</strong> aktivieren.</p><p>Erteilen Sie den Zugriff, wenn Sie beim ersten Start dazu aufgefordert werden. Sie können ihn jederzeit verwalten oder widerrufen.</p><h2 id="accessibility-optional" tabindex="-1">Accessibility (optional) <a class="header-anchor" href="#accessibility-optional" aria-label="Permalink to &quot;Accessibility (optional)&quot;">​</a></h2><p>Einige Builds verwenden Accessibility, um globale Tastenkürzel bereitzustellen und das Verlaufs-Panel von überall zu aktivieren.</p><p><strong>Verwendungszweck</strong>: Das Verlaufs-Panel öffnen und Aktionen über Hotkeys ausführen, selbst wenn die App nicht den Fokus hat.</p><p><strong>Verwalten</strong>: <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit → Accessibility</strong> → <strong>ClipboxAI</strong> aktivieren.</p><h2 id="benachrichtigungen-optional" tabindex="-1">Benachrichtigungen (optional) <a class="header-anchor" href="#benachrichtigungen-optional" aria-label="Permalink to &quot;Benachrichtigungen (optional)&quot;">​</a></h2><p>ClipboxAI kann Benachrichtigungen anzeigen, wenn eine länger laufende Aktion abgeschlossen ist oder Aufmerksamkeit benötigt.</p><p><strong>Verwendungszweck</strong>: Sie zu benachrichtigen, wenn eine Aktion endet oder eine Konfiguration erforderlich ist.</p><p><strong>Verwalten</strong>: <strong>Systemeinstellungen → Benachrichtigungen</strong> → <strong>ClipboxAI</strong>.</p><h2 id="full-disk-access-optional" tabindex="-1">Full Disk Access (optional) <a class="header-anchor" href="#full-disk-access-optional" aria-label="Permalink to &quot;Full Disk Access (optional)&quot;">​</a></h2><p>Für die normale Nutzung nicht erforderlich. Nur nötig, wenn die App Ausschnitte aus systemgeschützten Orten lesen soll.</p><p><strong>Verwalten</strong>: <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit → Full Disk Access</strong>.</p><p>Diese Berechtigung ist optional und nur in fortgeschrittenen Szenarien nötig.</p><h2 id="zurucksetzen-einer-berechtigung-mit-terminal" tabindex="-1">Zurücksetzen einer Berechtigung mit Terminal <a class="header-anchor" href="#zurucksetzen-einer-berechtigung-mit-terminal" aria-label="Permalink to &quot;Zurücksetzen einer Berechtigung mit Terminal&quot;">​</a></h2><p>Falls ein Berechtigungsdialog abgelehnt wurde oder der Zustand inkonsistent ist, können Sie die macOS-Berechtigungsabfragen mit <code>tccutil</code> zurücksetzen:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reset automation/accessibility prompts for ClipboxAI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.clipboard</span></span></code></pre></div><p>Nach dem Ausführen von <code>tccutil</code> starten Sie die App neu und lösen die Funktion erneut aus, um erneut gefragt zu werden.</p><h2 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h2><ul><li>Falls der Zwischenablagen-Verlauf Kopien nicht erfasst, prüfen Sie, ob die Berechtigung <strong>Automation</strong> erteilt ist.</li><li>Falls globale Tastenkürzel nicht funktionieren, prüfen Sie die Berechtigung <strong>Accessibility</strong>.</li><li>Ändern Sie nach dem Anpassen von Berechtigungen immer ClipboxAI, damit die Änderungen wirksam werden.</li></ul><p>Weitere Hilfe finden Sie im <a href="/de/guide/troubleshooting.html">Leitfaden zur Fehlerbehebung</a>.</p>`,26)])])}const p=n(s,[["render",r]]);export{d as __pageData,p as default};
